window.DiseaseRulesKB = {"version":"2023+2024-nhc-8guides","updatedAt":"2026-08-31","meta":{"description":"疾病饮食规则知识库：从国家卫健委 8 项食养指南（2023+2024 年版）结构化提取，供规则引擎按用户健康档案触发","sources":["国家卫生健康委办公厅《成人肥胖食养指南（2024年版）》国卫办食品函〔2024〕53号","国家卫生健康委办公厅《儿童青少年肥胖食养指南（2024年版）》国卫办食品函〔2024〕53号","国家卫生健康委办公厅《成人慢性肾脏病食养指南（2024年版）》国卫办食品函〔2024〕53号","国家卫生健康委办公厅《成人高尿酸血症与痛风食养指南（2024年版）》国卫办食品函〔2024〕53号","国家卫生健康委办公厅《成人糖尿病食养指南（2023年版）》国卫办食品函〔2023〕5号","国家卫生健康委办公厅《成人高血压食养指南（2023年版）》国卫办食品函〔2023〕5号","国家卫生健康委办公厅《成人高脂血症食养指南（2023年版）》国卫办食品函〔2023〕5号","国家卫生健康委办公厅《儿童青少年生长迟缓食养指南（2023年版）》国卫办食品函〔2023〕5号"]},"conditions":[{"id":"obesity","name":"成人肥胖 / 减重","appliesTo":["adult"],"source":"《成人肥胖食养指南（2024年版）》","principles":["控制总能量摄入，保持合理膳食","少吃高能量食物，饮食清淡，限制饮酒","纠正不良饮食行为，科学进餐","多动少静，睡眠充足，作息规律","食养有道，合理选择食药物质","安全减重，达到并保持健康体重"],"flags":[{"category":"含糖饮料","terms":["可乐","汽水","碳酸饮料","果味饮料","乳酸菌饮料","奶茶","含糖饮料","冰糖雪梨","冰红茶"],"level":"warning","reason":"减重期应避免含糖饮料：液体糖不顶饱，最容易不知不觉喝超"},{"category":"油炸食品","terms":["油炸","炸鸡","薯条","薯片","油条","油饼","炸"],"level":"warning","reason":"高能量食物（≥400kcal/100g），指南建议减重期少吃"},{"category":"高糖零食","terms":["糖果","蜜饯","冰淇淋","雪糕","巧克力","蛋糕","甜甜圈","沙琪玛"],"level":"warning","reason":"指南点名的高能量食物，减重期尽量不选"},{"category":"加工肉制品","terms":["香肠","火腿肠","培根","腊肉","午餐肉","熏肉","肉脯"],"level":"warning","reason":"指南建议采购时尽量不选加工肉制品"},{"category":"动物脂肪/起酥油","terms":["肥肉","猪油","牛油","羊油","起酥油","人造奶油","植脂末","氢化植物油"],"level":"warning","reason":"高脂肪食材，减重期严格控制脂肪摄入"},{"category":"酒精","terms":["白酒","啤酒","黄酒","葡萄酒","料酒","酒精"],"level":"warning","reason":"每克酒精约 7kcal，远超碳水和蛋白质，减重期严格限制饮酒"}],"nutrientLimits":{"salt_g_day":"≤5","oil_g_day":"20~25","added_sugar_g_day":"≤25","energy_note":"每日能量摄入平均降低 30%~50%，或降低 500~1000kcal；男性 1200~1500kcal/日，女性 1000~1200kcal/日","macros":"脂肪供能比 20%~30%，蛋白质 15%~20%，碳水化合物 50%~60%；三餐供能比 3:4:3"},"tips":["主食以全谷物为主，至少占谷物的一半，减少精白米面","新鲜蔬菜每天 300~500g，深色蔬菜占一半以上；每天 3~5 种","水果每天约 200g，少选榴莲、香蕉、荔枝、鲜枣等高糖水果，不喝果汁","鱼虾蟹贝每周至少 2 次（每天 40~75g）；畜禽肉每周不超 500g，选纯瘦肉","蛋类每周 280~350g（不超过 7 个）","低脂或脱脂奶每天 300~500mL；豆制品选豆腐、无糖豆浆，避开油炸豆制品","坚果每周 50~70g（每天约 10g），首选原味","晚餐建议 17:00~19:00，餐后不再进食；按蔬菜→肉类→主食顺序进餐","理想减重目标：6 个月减当前体重 5%~10%，每月 2~4kg"]},{"id":"obesity_child","name":"儿童青少年肥胖","appliesTo":["child_1_3","child_3_12"],"source":"《儿童青少年肥胖食养指南（2024年版）》","principles":["小份多样，保持合理膳食结构","辨证施食，因人因时因地制宜","良好饮食行为，促进长期健康","积极身体活动，保持身心健康","多方合作，创造社会支持环境","定期监测，科学指导体重管理"],"flags":[{"category":"含糖饮料","terms":["可乐","汽水","碳酸饮料","果味饮料","乳酸菌饮料","奶茶","含糖饮料","冰糖雪梨","冰红茶"],"level":"warning","reason":"含糖饮料是儿童肥胖的重要推手，指南建议减少摄入"},{"category":"油炸食品","terms":["油炸","炸鸡","薯条","薯片","油条"],"level":"warning","reason":"高油高能量密度食物，肥胖儿童应少吃"},{"category":"甜点糖果","terms":["糖果","甜点","冰淇淋","雪糕","巧克力","蛋糕","蜜饯"],"level":"warning","reason":"高糖高能量密度，指南建议肥胖儿童减少摄入"}],"nutrientLimits":{"energy_note":"肥胖儿童膳食能量在正常体重儿童需要量基础上减少约 20%，吃饭八分饱","milk_ml_day":"2~5 岁 350~500mL；6~17 岁 300mL 以上","food_variety":"每天 12 种以上食物，每周 25 种以上"},"tips":["吃饭八分饱，控制膳食总能量","多选天然新鲜食材，提高鱼类、蔬菜、大豆及制品比例","控制精白米面，增加低血糖生成指数的全谷物和杂豆","减少高油、高盐、高糖和能量密度较高的食物","保证优质蛋白质：鱼、禽、蛋、瘦肉、奶及奶制品、大豆及制品","选择小份量食物实现食物多样，每天 12 种、每周 25 种以上"]},{"id":"ckd","name":"成人慢性肾脏病","appliesTo":["adult"],"source":"《成人慢性肾脏病食养指南（2024年版）》","principles":["食物多样，分期选配","能量充足，体重合理，谷物适宜，主食优化","蛋白适量，合理摄入鱼禽豆蛋奶肉","蔬菜充足，水果适量","少盐控油，限磷控钾","适量饮水，量出为入","合理选择食药物质，调补有道","合理选择营养健康食品，改善营养状况","规律进餐，限制饮酒，适度运动","定期监测，强化自我管理"],"flags":[{"category":"高盐/隐形盐","terms":["食盐","食用盐","酱油","味精","鸡精","豆瓣酱","腐乳","酱料","蚝油"],"level":"warning","reason":"肾病每日盐不超 5g（水肿者 3g），调味品都是隐形盐"},{"category":"烟熏烧烤腌制","terms":["烟熏","烧烤","腌制","咸菜","榨菜","泡菜","腊肉","咸鱼","熏"],"level":"warning","reason":"指南建议肾病患者尽量不吃烟熏、烧烤、腌制等过度加工食品"},{"category":"含磷添加剂","terms":["磷酸盐","三聚磷酸钠","焦磷酸钠","六偏磷酸钠","磷酸氢","磷酸二氢","磷酸"],"level":"warning","reason":"加工食品中的含磷添加剂吸收率远高于天然食物，肾病需限磷（每日 800~1000mg）"},{"category":"浓肉汤/高汤","terms":["肉汤","骨汤","老火汤","高汤","浓汤"],"level":"warning","reason":"浓肉汤高钾高磷，肾病患者应限制或禁食"},{"category":"酒精","terms":["白酒","啤酒","黄酒","葡萄酒","酒精"],"level":"warning","reason":"肾病患者应限酒或不饮酒"}],"nutrientLimits":{"salt_g_day":"≤5（水肿者 ≤3；严重水肿无盐膳食钠＜1000mg）","phosphorus_mg_day":"800~1000","potassium_mg_day":"高钾血症时 2000~3000，避免浓肉汤、菜汤，烹调先飞水弃汤","protein_note":"3~5 期低蛋白饮食：每日每公斤理想体重 0.6g，优质蛋白占 50% 以上；理想体重(kg)=身高(cm)-105","oil_g_day":"25~40，脂肪供能比 ≤35%","water_ml_day":"无水肿且尿量正常者 1500~1700；水肿者量出为入","food_variety":"每日 12 种以上，每周 25 种以上"},"tips":["1~2 期：植物性食物为主，餐餐有蔬菜 300~500g，深色占一半","3~5 期：低蛋白饮食，可用红薯、土豆、莲藕、山药、绿豆粉丝替代部分谷物","红肉（猪牛羊）尽量少吃，每周 1~2 次、每次不超 50g；优先鱼禽白肉","学会看营养标签，避开含磷添加剂多的加工食品","烹调选清蒸、炖、焖、煮；先飞水后烹调可减少磷和钾","5 期透析阶段仍需植物性食物为主，按医嘱调整动物性食物"]},{"id":"hyperuricemia","name":"高尿酸血症 / 痛风","appliesTo":["adult"],"source":"《成人高尿酸血症与痛风食养指南（2024年版）》","principles":["食物多样，限制嘌呤","蔬奶充足，限制果糖","足量饮水，限制饮酒","科学烹饪，少食生冷","吃动平衡，健康体重","辨证辨体，因人施膳","因地因时，择膳相宜"],"flags":[{"category":"酒精","terms":["啤酒","黄酒","白酒","酒精"],"level":"danger","reason":"酒精抑制尿酸排泄，啤酒黄酒嘌呤还高，痛风人群严格限制"},{"category":"高果糖","terms":["果葡糖浆","高果糖","玉米糖浆","含糖饮料","可乐","奶茶"],"level":"warning","reason":"果糖代谢促进尿酸生成，指南建议限制果糖摄入"},{"category":"动物内脏/高汤","terms":["动物内脏","肝","肾","脑","肠","肉汤","骨汤","高汤","火锅汤"],"level":"warning","reason":"动物内脏和浓汤嘌呤极高，痛风人群避免"}],"nutrientLimits":{"purine_note":"避免高嘌呤食物（150~1000mg/100g），限制中嘌呤（75~150mg/100g），详见嘌呤知识库 236 条","water_ml_day":"2000~3000（心肾功能正常者），促进尿酸排泄","fructose_note":"限制含果糖饮料和食品"},"tips":["每天饮水 2000~3000mL，白开水、淡茶水为宜","新鲜蔬菜每天不少于 500g，深色蔬菜占一半以上","低脂或脱脂奶每天 300mL 以上","限制果糖：少喝含糖饮料，蜂蜜也要控制","严格限酒，急性期禁酒；啤酒、黄酒最危险","科学烹饪：肉类先焯水弃汤再煮，少喝肉汤"]},{"id":"diabetes","name":"成人糖尿病","appliesTo":["adult"],"source":"《成人糖尿病食养指南（2023年版）》国卫办食品函〔2023〕5号","principles":["食物多样，养成和建立合理膳食习惯","能量适宜，控制超重肥胖和预防消瘦","主食定量，优选全谷物和低血糖生成指数食物","积极运动，改善体质和胰岛素敏感性","清淡饮食，限制饮酒，预防和延缓并发症","食养有道，合理选择应用食药物质","规律进餐，合理加餐，促进餐后血糖稳定","自我管理，定期营养咨询，提高血糖控制能力"],"flags":[{"category":"添加糖/含糖饮料","terms":["白砂糖","冰糖","红糖","果葡糖浆","葡萄糖浆","麦芽糖浆","蜂蜜","可乐","汽水","碳酸饮料","奶茶","含糖饮料","乳酸菌饮料"],"level":"danger","reason":"添加糖直接拉升餐后血糖，指南要求限糖，含糖饮料应避免"},{"category":"高糖零食甜点","terms":["糖果","蜜饯","冰淇淋","雪糕","巧克力","蛋糕","甜甜圈","沙琪玛","饼干"],"level":"warning","reason":"高糖高能量，引起餐后血糖大幅波动，糖尿病患者尽量不选"},{"category":"油炸高脂食品","terms":["油炸","炸鸡","薯条","薯片","油条","油饼"],"level":"warning","reason":"高脂肪高能量，加重胰岛素抵抗，指南建议少油"},{"category":"加工肉制品","terms":["香肠","火腿肠","培根","腊肉","午餐肉","熏肉"],"level":"warning","reason":"指南建议少吃烟熏、烘烤、腌制等加工肉类制品"},{"category":"酒精","terms":["白酒","啤酒","黄酒","葡萄酒","酒精"],"level":"warning","reason":"酒精干扰血糖稳定并增加并发症风险，糖尿病患者应限制饮酒"}],"nutrientLimits":{"macros":"蛋白质 15%~20%，碳水化合物 45%~60%，脂肪 20%~35%","vegetable_g_day":"≥500，深色蔬菜占一半以上","staple_note":"主食定量，全谷物和杂豆等低 GI 食物占 1/3 以上","bmi":"18.5~23.9；超重肥胖者每月减 1~2kg，3~6 个月减重 5%~10%","meals":"规律进餐，合理加餐，促进餐后血糖稳定"},"tips":["主食定量不多吃，优选全谷物、杂豆等低 GI 食物","餐餐有蔬菜，每天 500g 以上，深色占一半","天天有奶类和大豆，常吃鱼禽，适量蛋和畜肉，减少肥肉","少油少盐限糖限酒，水果限量不喝果汁","规律进餐、定时定量，必要时合理加餐防低血糖","定期监测血糖，每 3~6 个月做一次营养咨询"]},{"id":"hypertension","name":"成人高血压","appliesTo":["adult"],"source":"《成人高血压食养指南（2023年版）》国卫办食品函〔2023〕5号","principles":["减钠增钾，饮食清淡","合理膳食，科学食养","吃动平衡，健康体重","戒烟限酒，心理平衡","监测血压，自我管理"],"flags":[{"category":"高盐/隐形盐","terms":["食盐","食用盐","酱油","味精","鸡精","蚝油","豆瓣酱","腐乳","酱料","咸菜","榨菜"],"level":"danger","reason":"高血压每日食盐逐步降至 5g 以下，调味品和腌菜都是隐形盐大户"},{"category":"加工肉制品","terms":["培根","香肠","腊肠","腊肉","火腿","午餐肉"],"level":"warning","reason":"指南点名少吃加工红肉制品，高盐高脂"},{"category":"动物内脏/油炸","terms":["动物内脏","肝","脑","油炸","炸鸡","油条"],"level":"warning","reason":"高脂肪高胆固醇，增加冠心病、脑卒中风险"},{"category":"酒精","terms":["白酒","啤酒","黄酒","葡萄酒","酒精"],"level":"warning","reason":"过量饮酒是高血压危险因素，指南建议限制饮酒"}],"nutrientLimits":{"salt_g_day":"<5（逐步降至），警惕调味品与加工食品中的隐形盐","potassium_note":"增加富钾食物（新鲜蔬菜、水果、豆类）；肾功能良好者可选高钾低钠盐，肾功能不全者先咨询医生","energy_note":"18~49 岁轻体力活动：男性约 2250kcal/日，女性约 1800kcal/日","bmi_waist":"BMI 18.5~23.9；男性腰围 <85cm，女性 <80cm"},"tips":["每日食盐逐步降到 5g 以下，用限盐勺，出锅前放盐","多吃富钾蔬果和豆类，深色蔬菜占一半以上","全谷物或杂豆占谷类 1/4~1/2","蛋白质多选奶类、鱼类、大豆制品","限制添加糖，少吃油炸食品和动物内脏","戒烟限酒，保持心理平衡，定期监测血压"]},{"id":"hyperlipidemia","name":"成人高脂血症","appliesTo":["adult"],"source":"《成人高脂血症食养指南（2023年版）》国卫办食品函〔2023〕5号","principles":["吃动平衡，保持健康体重","调控脂肪，少油烹饪","食物多样，蛋白质和膳食纤维摄入充足","少盐控糖，戒烟限酒","因人制宜，辨证施膳","因时制宜，分季调理","因地制宜，合理搭配","会看慧选，科学食养，适量食用食药物质"],"flags":[{"category":"反式脂肪酸","terms":["氢化植物油","部分氢化植物油","植脂末","人造奶油","人造黄油","起酥油","代可可脂","精炼植物油"],"level":"danger","reason":"反式脂肪酸每天不宜超过 2g，配料表出现氢化油脂要警惕"},{"category":"高胆固醇食材","terms":["动物脑","动物内脏","肝","肾","脑","蛋黄酱"],"level":"warning","reason":"胆固醇每日少于 300mg（高胆固醇血症者少于 200mg），少吃动物脑和内脏"},{"category":"油炸/高饱和脂肪","terms":["油炸","炸鸡","薯条","油条","肥肉","猪油","牛油","棕榈油","椰子油"],"level":"warning","reason":"饱和脂肪应少于总能量 10%（高胆固醇血症者 7%），烹调油每日不超 25g"},{"category":"高糖","terms":["白砂糖","果葡糖浆","糖果","蜜饯","含糖饮料","奶茶"],"level":"warning","reason":"指南要求少盐控糖，高糖饮食升高甘油三酯"},{"category":"酒精","terms":["白酒","啤酒","黄酒","葡萄酒","酒精"],"level":"warning","reason":"酒精升高甘油三酯，高脂血症人群应戒烟限酒"}],"nutrientLimits":{"fat_energy_pct":"20%~25%（约 40~55g/日），烹调油 ≤25g/日","saturated_fat":"<总能量 10%；高胆固醇血症者 <7%","cholesterol_mg_day":"<300；高胆固醇血症者 <200","trans_fat_g_day":"<2（低于总能量 1%）","salt_g_day":"<5","exercise":"每周 5~7 次、每次 30 分钟中等强度，每天消耗 ≥200kcal"},"tips":["烹调油每天不超 25g，选蒸、煮、炖、焖，少煎炸","配料表看到「氢化植物油、植脂末、人造奶油」要警惕反式脂肪","适当增加富含 n-3 多不饱和脂肪酸的鱼类","动物脑、动物内脏少吃，鸡蛋每天不超 1 个","少盐控糖，戒烟限酒","超重者每天减少 300~500kcal 能量摄入"]},{"id":"growth_retardation","name":"儿童青少年生长迟缓","appliesTo":["child_1_3","child_3_12"],"source":"《儿童青少年生长迟缓食养指南（2023年版）》国卫办食品函〔2023〕5号","principles":["食物多样，满足生长发育需要","因人因地因时食养，调理脾胃","合理烹调，培养健康饮食行为","开展营养教育，营造健康食物环境","保持适宜的身体活动，关注睡眠和心理健康","定期监测体格发育，强化膳食评估和指导"],"flags":[{"category":"含糖饮料/高糖零食","terms":["可乐","汽水","碳酸饮料","奶茶","含糖饮料","糖果","蜜饯","巧克力","冰淇淋"],"level":"warning","reason":"高糖零食挤占正餐食欲，加重挑食偏食，不利于追赶生长"},{"category":"油炸/高能量密度零食","terms":["油炸","炸鸡","薯条","薯片","方便面"],"level":"warning","reason":"高能量低营养密度，影响正餐摄入和膳食质量"}],"nutrientLimits":{"milk_ml_day":"2~5 岁 350~500mL；6~17 岁 300mL 以上液态奶或相当量奶制品","food_variety":"每天 12 种以上食物，每周 25 种以上；每餐含 3 类及以上食物","meals":"2~5 岁每天 3 次正餐 + 2 次加餐；6~17 岁合理安排三餐，吃好早餐","water_ml_day":"2~5 岁饮水 600~800mL"},"tips":["适当增加瘦肉、水产品、禽类、蛋类、大豆等优质蛋白质","每天喝奶补钙，注意补充维生素 D（遵医嘱）","增加动物肝脏、动物血等富铁食物，预防缺铁性贫血","同类食物互换避免长期单一主食：杂粮薯类替代部分米面","少油少盐少糖，合理烹调，培养健康饮食行为","定期监测身高体重，必要时寻求营养指导"]}]};
